P=/dd/CMDS/NETPBMecho "@@CASE@@pgmramp-makes-a-ramp"$P/pgmramp -lr 32 8 > /dd/tmp/s.pgm$P/pnmfile /dd/tmp/s.pgmecho "@@CASE@@pnmcut-really-crops"$P/pnmcut 0 0 16 4 /dd/tmp/s.pgm > /dd/tmp/c.pgm$P/pnmfile /dd/tmp/c.pgmecho "@@CASE@@pnmtile-really-tiles"$P/pnmtile 64 16 /dd/tmp/s.pgm > /dd/tmp/t.pgm$P/pnmfile /dd/tmp/t.pgmecho "@@CASE@@pnmscale-doubles"$P/pnmscale 2 /dd/tmp/s.pgm > /dd/tmp/d.pgm$P/pnmfile /dd/tmp/d.pgmecho "@@CASE@@pnmpad-adds-a-border"$P/pnmpad -white -l4 -r4 /dd/tmp/s.pgm > /dd/tmp/pd.pgm$P/pnmfile /dd/tmp/pd.pgmecho "@@CASE@@pnmenlarge-triples"$P/pnmenlarge 3 /dd/tmp/s.pgm > /dd/tmp/en.pgm$P/pnmfile /dd/tmp/en.pgmecho "@@CASE@@ppmmake-names-colours"$P/ppmmake blue 3 2 > /dd/tmp/b.ppm$P/pnmnoraw /dd/tmp/b.ppmecho "@@CASE@@pnminvert-is-its-own-inverse"$P/pnminvert /dd/tmp/s.pgm > /dd/tmp/i1.pgm$P/pnminvert /dd/tmp/i1.pgm > /dd/tmp/i2.pgm$P/pnmarith -difference /dd/tmp/s.pgm /dd/tmp/i2.pgm > /dd/tmp/id.pgm$P/pgmhist /dd/tmp/id.pgmecho "@@CASE@@pnmflip-tb-twice-is-identity"$P/pnmflip -tb /dd/tmp/s.pgm > /dd/tmp/f1.pgm$P/pnmflip -tb /dd/tmp/f1.pgm > /dd/tmp/f2.pgm$P/pnmarith -difference /dd/tmp/s.pgm /dd/tmp/f2.pgm > /dd/tmp/fd.pgm$P/pgmhist /dd/tmp/fd.pgmecho "@@CASE@@pnmflip-lr-twice-is-identity"$P/pnmflip -lr /dd/tmp/s.pgm > /dd/tmp/g1.pgm$P/pnmflip -lr /dd/tmp/g1.pgm > /dd/tmp/g2.pgm$P/pnmarith -difference /dd/tmp/s.pgm /dd/tmp/g2.pgm > /dd/tmp/gd.pgm$P/pgmhist /dd/tmp/gd.pgmecho "@@CASE@@make-a-bilevel-source"$P/pgmtopbm /dd/tmp/s.pgm > /dd/tmp/r.pbm$P/pnmfile /dd/tmp/r.pbmecho "@@CASE@@xbm-round-trip-is-lossless"$P/pbmtoxbm /dd/tmp/r.pbm > /dd/tmp/r.xbm 2>/nil$P/xbmtopbm /dd/tmp/r.xbm > /dd/tmp/x.pbm 2>/nil$P/pnmarith -difference /dd/tmp/r.pbm /dd/tmp/x.pbm > /dd/tmp/xd.pbm$P/pgmhist /dd/tmp/xd.pbmecho "@@CASE@@icon-round-trip-is-lossless"$P/pbmtoicon /dd/tmp/r.pbm > /dd/tmp/r.icon 2>/nil$P/icontopbm /dd/tmp/r.icon > /dd/tmp/y.pbm 2>/nil$P/pnmarith -difference /dd/tmp/r.pbm /dd/tmp/y.pbm > /dd/tmp/yd.pbm$P/pgmhist /dd/tmp/yd.pbmecho "@@CASE@@ybm-round-trip-is-lossless"$P/pbmtoybm /dd/tmp/r.pbm > /dd/tmp/r.ybm 2>/nil$P/ybmtopbm /dd/tmp/r.ybm > /dd/tmp/z.pbm 2>/nil$P/pnmarith -difference /dd/tmp/r.pbm /dd/tmp/z.pbm > /dd/tmp/zd.pbm$P/pgmhist /dd/tmp/zd.pbmecho "@@CASE@@g3-round-trip-is-lossless"$P/pbmtog3 /dd/tmp/r.pbm > /dd/tmp/r.g3 2>/nil$P/g3topbm /dd/tmp/r.g3 > /dd/tmp/w.pbm 2>/nil$P/pnmarith -difference /dd/tmp/r.pbm /dd/tmp/w.pbm > /dd/tmp/wd.pbm$P/pgmhist /dd/tmp/wd.pbmecho "@@CASE@@macp-round-trip-is-lossless"$P/pbmtomacp /dd/tmp/r.pbm > /dd/tmp/r.macp 2>/nil$P/macptopbm /dd/tmp/r.macp > /dd/tmp/m.pbm 2>/nil$P/pnmcut 0 0 32 8 /dd/tmp/m.pbm > /dd/tmp/mc.pbm$P/pnmarith -difference /dd/tmp/r.pbm /dd/tmp/mc.pbm > /dd/tmp/md.pbm$P/pgmhist /dd/tmp/md.pbmecho "@@CASE@@cmuwm-round-trip-is-lossless"$P/pbmtocmuwm /dd/tmp/r.pbm > /dd/tmp/r.cmuwm 2>/nil$P/cmuwmtopbm /dd/tmp/r.cmuwm > /dd/tmp/cm.pbm 2>/nil$P/pnmarith -difference /dd/tmp/r.pbm /dd/tmp/cm.pbm > /dd/tmp/cmd.pbm$P/pgmhist /dd/tmp/cmd.pbmecho "@@CASE@@mgr-round-trip-is-lossless"$P/pbmtomgr /dd/tmp/r.pbm > /dd/tmp/r.mgr 2>/nil$P/mgrtopbm /dd/tmp/r.mgr > /dd/tmp/mg.pbm 2>/nil$P/pnmarith -difference /dd/tmp/r.pbm /dd/tmp/mg.pbm > /dd/tmp/mgd.pbm$P/pgmhist /dd/tmp/mgd.pbmecho "@@CASE@@atk-round-trip-is-lossless"$P/pbmtoatk /dd/tmp/r.pbm > /dd/tmp/r.atk 2>/nil$P/atktopbm /dd/tmp/r.atk > /dd/tmp/at.pbm 2>/nil$P/pnmarith -difference /dd/tmp/r.pbm /dd/tmp/at.pbm > /dd/tmp/atd.pbm$P/pgmhist /dd/tmp/atd.pbmecho "@@CASE@@gem-round-trip-is-lossless"$P/pbmtogem /dd/tmp/r.pbm > /dd/tmp/r.gem 2>/nil$P/gemtopbm /dd/tmp/r.gem > /dd/tmp/ge.pbm 2>/nil$P/pnmarith -difference /dd/tmp/r.pbm /dd/tmp/ge.pbm > /dd/tmp/ged.pbm$P/pgmhist /dd/tmp/ged.pbmecho "@@CASE@@make-a-colour-source"$P/pgmtoppm red-blue /dd/tmp/s.pgm > /dd/tmp/c.ppm$P/pnmfile /dd/tmp/c.ppmecho "@@CASE@@gif-round-trip-is-lossless"$P/ppmtogif /dd/tmp/c.ppm > /dd/tmp/r.gif 2>/nil$P/giftopnm /dd/tmp/r.gif > /dd/tmp/gi.ppm 2>/nil$P/pnmarith -difference /dd/tmp/c.ppm /dd/tmp/gi.ppm > /dd/tmp/gid.ppm$P/ppmhist /dd/tmp/gid.ppmecho "@@CASE@@pcx-round-trip-is-lossless"$P/ppmtopcx /dd/tmp/c.ppm > /dd/tmp/r.pcx 2>/nil$P/pcxtoppm /dd/tmp/r.pcx > /dd/tmp/px.ppm 2>/nil$P/pnmarith -difference /dd/tmp/c.ppm /dd/tmp/px.ppm > /dd/tmp/pxd.ppm$P/ppmhist /dd/tmp/pxd.ppmecho "@@CASE@@bmp-round-trip-is-lossless"$P/ppmtobmp /dd/tmp/c.ppm > /dd/tmp/r.bmp 2>/nil$P/bmptoppm /dd/tmp/r.bmp > /dd/tmp/bm.ppm 2>/nil$P/pnmarith -difference /dd/tmp/c.ppm /dd/tmp/bm.ppm > /dd/tmp/bmd.ppm$P/ppmhist /dd/tmp/bmd.ppmecho "@@CASE@@tga-round-trip-is-lossless"$P/ppmtotga /dd/tmp/c.ppm > /dd/tmp/r.tga 2>/nil$P/tgatoppm /dd/tmp/r.tga > /dd/tmp/tg.ppm 2>/nil$P/pnmarith -difference /dd/tmp/c.ppm /dd/tmp/tg.ppm > /dd/tmp/tgd.ppm$P/ppmhist /dd/tmp/tgd.ppmecho "@@CASE@@sgi-round-trip-is-lossless"$P/pnmtosgi /dd/tmp/c.ppm > /dd/tmp/r.sgi 2>/nil$P/sgitopnm /dd/tmp/r.sgi > /dd/tmp/sg.ppm 2>/nil$P/pnmarith -difference /dd/tmp/c.ppm /dd/tmp/sg.ppm > /dd/tmp/sgd.ppm$P/ppmhist /dd/tmp/sgd.ppmecho "@@CASE@@rast-round-trip-is-lossless"$P/pnmtorast /dd/tmp/c.ppm > /dd/tmp/r.rast 2>/nil$P/rasttopnm /dd/tmp/r.rast > /dd/tmp/ra.ppm 2>/nil$P/pnmarith -difference /dd/tmp/c.ppm /dd/tmp/ra.ppm > /dd/tmp/rad.ppm$P/ppmhist /dd/tmp/rad.ppmecho "@@CASE@@ilbm-round-trip-is-lossless"$P/ppmtoilbm /dd/tmp/c.ppm > /dd/tmp/r.ilbm 2>/nil$P/ilbmtoppm /dd/tmp/r.ilbm > /dd/tmp/il.ppm 2>/nil$P/pnmarith -difference /dd/tmp/c.ppm /dd/tmp/il.ppm > /dd/tmp/ild.ppm$P/ppmhist /dd/tmp/ild.ppmecho "@@CASE@@xpm-round-trip-is-lossless"$P/ppmtoxpm /dd/tmp/c.ppm > /dd/tmp/r.xpm 2>/nil$P/xpmtoppm /dd/tmp/r.xpm > /dd/tmp/xp.ppm 2>/nil$P/pnmarith -difference /dd/tmp/c.ppm /dd/tmp/xp.ppm > /dd/tmp/xpd.ppm$P/ppmhist /dd/tmp/xpd.ppmecho "@@CASE@@ppmnorm-normalises"$P/ppmnorm /dd/tmp/c.ppm > /dd/tmp/nm.ppm 2>/nil$P/pnmfile /dd/tmp/nm.ppmecho "@@CASE@@sir-round-trip-is-lossy"$P/ppmmake red 4 1 > /dd/tmp/k.ppm 2>/nil$P/pnmtosir /dd/tmp/k.ppm > /dd/tmp/k.sir 2>/nil$P/sirtopnm /dd/tmp/k.sir > /dd/tmp/k2.ppm 2>/nil$P/pnmnoraw /dd/tmp/k2.ppmecho "@@CASE@@pbmtext-renders-text"$P/pbmtext hello > /dd/tmp/tx.pbm 2>/nil$P/pnmfile /dd/tmp/tx.pbmecho "@@CASE@@wrong-format-diagnosed-not-crashed"$P/fstopgm /dd/tmp/c.ppm > /nil$P/hipstopgm /dd/tmp/c.ppm > /nil$P/xvminitoppm /dd/tmp/c.ppm > /nilecho "@@CASE@@rgb3-round-trip-is-lossless"$P/ppmtorgb3 /dd/tmp/c.ppm 2>/nil$P/rgb3toppm /dd/tmp/c.red /dd/tmp/c.grn /dd/tmp/c.blu > /dd/tmp/rg.ppm 2>/nil$P/pnmarith -difference /dd/tmp/c.ppm /dd/tmp/rg.ppm > /dd/tmp/rgd.ppm$P/ppmhist /dd/tmp/rgd.ppmecho "@@CASE@@yuv-round-trip-survives"$P/ppmtoyuv /dd/tmp/c.ppm > /dd/tmp/r.yuv 2>/nil$P/yuvtoppm 32 8 /dd/tmp/r.yuv > /dd/tmp/yu.ppm 2>/nil$P/pnmfile /dd/tmp/yu.ppmecho "@@CASE@@pgmnorm-changes-something"$P/pgmnorm /dd/tmp/s.pgm > /dd/tmp/n.pgm 2>/nil$P/pnmfile /dd/tmp/n.pgmecho "@@CASE@@pgmedge-changes-something"$P/pgmedge /dd/tmp/s.pgm > /dd/tmp/e.pgm 2>/nil$P/pnmfile /dd/tmp/e.pgmecho "@@CASE@@ppmbrighten-changes-colour"$P/ppmbrighten -v 50 /dd/tmp/c.ppm > /dd/tmp/br.ppm 2>/nil$P/pnmfile /dd/tmp/br.ppmecho "@@CASE@@ppmdither-produces-an-image"$P/ppmdither /dd/tmp/c.ppm > /dd/tmp/di.ppm 2>/nil$P/pnmfile /dd/tmp/di.ppmecho "@@CASE@@pbmtoascii-draws-characters"$P/pbmtoascii /dd/tmp/r.pbmecho "@@CASE@@pnmcat-joins-two"$P/pnmcat -lr /dd/tmp/s.pgm /dd/tmp/s.pgm > /dd/tmp/j.pgm 2>/nil$P/pnmfile /dd/tmp/j.pgmecho "@@CASE@@pnmdepth-rescales-maxval"$P/pnmdepth 15 /dd/tmp/s.pgm > /dd/tmp/dp.pgm 2>/nil$P/pnmfile /dd/tmp/dp.pgmecho "@@CASE@@pbmmake-and-pbmtopgm"$P/pbmmake -w 16 4 > /dd/tmp/pm.pbm 2>/nil$P/pbmtopgm 3 3 /dd/tmp/pm.pbm > /dd/tmp/pm.pgm 2>/nil$P/pnmfile /dd/tmp/pm.pgmecho "@@CASE@@end"